<template>
  <section class="home-grid" data-testid="home-grid">
    <article class="surface-card home-card home-card--mods" @click="emit('navigate', 'mods')"><header><span class="home-card-icon material-icons">extension</span><strong>模组</strong><button aria-label="打开模组" @click.stop="emit('navigate', 'mods')"><span class="material-icons">open_in_new</span></button></header><div class="home-card-number">{{ counts.mods }}</div><small>已安装资源</small><div class="home-card-list"><div v-for="item in resources.mods.slice(0, 5)" :key="item.fileName"><span>{{ item.name || item.fileName }}</span><span class="material-icons">{{ item.enabled === false ? 'visibility_off' : 'check' }}</span></div><div v-if="loading && !resources.mods.length" class="home-empty">正在读取模组目录…</div><div v-else-if="!resources.mods.length" class="home-empty">没有安装模组</div></div><small v-if="info?.modsRoot" class="home-path" :title="info.modsRoot">目录：{{ info.modsRoot }}</small></article>
    <article class="surface-card home-card home-card--resources" @click="emit('navigate', 'resourcepacks')"><header><span class="home-card-icon material-icons">palette</span><strong>资源包</strong><button aria-label="打开资源包" @click.stop="emit('navigate', 'resourcepacks')"><span class="material-icons">open_in_new</span></button></header><div class="home-card-number">{{ counts.resourcepacks }}</div><small>已安装资源</small><div class="home-card-list"><div v-for="item in resources.resourcepacks.slice(0, 5)" :key="item.fileName"><span>{{ item.name || item.fileName }}</span><span class="material-icons">{{ item.enabled === false ? 'visibility_off' : 'check' }}</span></div><div v-if="loading && !resources.resourcepacks.length" class="home-empty">正在读取资源包目录…</div><div v-else-if="!resources.resourcepacks.length" class="home-empty">没有安装资源包</div></div><small v-if="info?.gameRoot" class="home-path" :title="info.gameRoot">游戏目录：{{ info.gameRoot }}</small></article>
    <article class="surface-card home-card home-card--worlds" @click="emit('navigate', 'save')"><header><span class="home-card-icon material-icons">public</span><strong>世界</strong><button aria-label="打开世界" @click.stop="emit('navigate', 'save')"><span class="material-icons">open_in_new</span></button></header><div class="home-card-number">{{ worlds.length }}</div><small>本地存档</small><div class="home-card-list"><div v-for="world in worlds.slice(0, 5)" :key="world.folder"><span>{{ world.name || world.folder }}</span><span class="material-icons">chevron_right</span></div><div v-if="!worlds.length" class="home-empty">没有发现世界</div></div></article>
    <article class="surface-card home-card home-card--screenshots" @click="emit('extras')"><header><span class="home-card-icon material-icons">photo_library</span><strong>截图</strong><button aria-label="打开截图"><span class="material-icons">open_in_new</span></button></header><div class="screenshot-grid"><img v-for="shot in screenshots.slice(0, 6)" :key="shot.name" :src="shot.dataUrl || shot.url" :alt="shot.name" /><div v-if="loading && !screenshots.length" class="home-empty">正在读取截图目录…</div><div v-else-if="!screenshots.length" class="home-empty">没有截图</div></div></article>
    <div v-if="error" class="home-error"><span class="material-icons">error</span>{{ error }}</div>
  </section>
</template>
<script setup lang="ts">
import { onMounted, reactive, ref, watch } from 'vue';
const props = defineProps<{ instance: string; execute: (op: string, p?: Record<string, unknown>) => Promise<any> }>();
const emit = defineEmits<{ navigate: [page: string]; extras: [] }>();
const resources = ref<Record<string, any[]>>({ mods: [], resourcepacks: [] }); const worlds = ref<any[]>([]); const screenshots = ref<any[]>([]); const info = ref<any>(null); const error = ref(''); const loading = ref(false); const counts = reactive({ mods: 0, resourcepacks: 0 }); let request = 0;
function readableError(e:any){if(e instanceof Error)return e.message;if(typeof e==='string')return e;if(e?.message)return readableError(e.message);if(e?.error)return readableError(e.error);try{return JSON.stringify(e);}catch{return String(e);}}
async function load() { const current = ++request; loading.value = true; error.value = ''; resources.value = { mods: [], resourcepacks: [] }; worlds.value = []; screenshots.value = []; info.value = null; counts.mods = 0; counts.resourcepacks = 0; const jobs = await Promise.allSettled([props.execute('resource.list', { instance: props.instance, kind: 'mods', includeIcons: false }), props.execute('resource.list', { instance: props.instance, kind: 'resourcepacks', includeIcons: false }), props.execute('instance.world.list', { instance: props.instance }), props.execute('instance.screenshot.list', { instance: props.instance }), props.execute('instance.info', { instance: props.instance })]); if (current !== request) return; const [mods, packs, w, s, details] = jobs; const value = (job: PromiseSettledResult<any>) => job.status === 'fulfilled' ? job.value : undefined; resources.value = { mods: Array.isArray(value(mods)) ? value(mods) : [], resourcepacks: Array.isArray(value(packs)) ? value(packs) : [] }; counts.mods = resources.value.mods.length; counts.resourcepacks = resources.value.resourcepacks.length; worlds.value = Array.isArray(value(w)) ? value(w) : []; screenshots.value = Array.isArray(value(s)) ? value(s) : []; info.value = value(details) || null; const firstFailure = jobs.find((job): job is PromiseRejectedResult => job.status === 'rejected'); if (firstFailure) error.value = readableError(firstFailure.reason); loading.value = false; }
watch(() => props.instance, load); onMounted(load);
</script>
<style scoped>
.home-grid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));grid-auto-rows:minmax(52px,auto);gap:14px;padding:0 1.25rem 2rem;max-width:1300px;margin:0 auto}.home-card{grid-column:span 3;grid-row:span 5;min-height:260px;padding:16px;border-radius:12px;cursor:pointer;transition:transform .2s,box-shadow .2s,border-color .2s}.home-card:hover{transform:translateY(-3px);box-shadow:0 12px 28px rgba(0,0,0,.28);border-color:rgba(255,255,255,.28)}.home-card header{display:flex;align-items:center;gap:8px;height:32px}.home-card header strong{flex:1;font-size:16px}.home-card header button{border:0;background:transparent;color:rgba(255,255,255,.55);cursor:pointer}.home-card header button:hover{color:#fff}.home-card-icon{color:rgb(var(--v-theme-primary,99 102 241));font-size:21px}.home-card-number{font-size:42px;line-height:1.1;margin-top:18px;font-weight:700}.home-card small{color:rgba(255,255,255,.58)}.home-card-list{margin-top:18px;display:flex;flex-direction:column;gap:5px}.home-card-list>div{display:flex;justify-content:space-between;align-items:center;padding:7px 9px;border-radius:7px;background:rgba(255,255,255,.05);font-size:12px}.home-card-list span:first-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.home-empty{color:rgba(255,255,255,.42)!important;background:transparent!important;justify-content:center!important;padding-top:20px!important}.home-card--screenshots{grid-column:span 6}.screenshot-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-top:18px}.screenshot-grid img{width:100%;height:72px;object-fit:cover;border-radius:7px;background:#15151b}.screenshot-grid .home-empty{grid-column:1/-1}@media(max-width:1050px){.home-card{grid-column:span 6}.home-card--screenshots{grid-column:span 12}}@media(max-width:650px){.home-grid{display:flex;flex-direction:column;padding:0 8px 24px}.home-card{min-height:220px}}
.material-icons{font-size:20px;line-height:1}
.home-path{display:block;margin-top:10px;color:rgba(255,255,255,.35);font-size:10px;line-height:1.35;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.home-error{grid-column:1/-1;display:flex;align-items:center;gap:8px;padding:10px 12px;border:1px solid rgba(248,113,113,.45);border-radius:9px;background:rgba(127,29,29,.25);color:#fecaca;font-size:12px}.home-error .material-icons{font-size:18px}
</style>
